UPDATE board.board
SET board_title = #{boardTitle} , board_content = #{boardContent}
WHERE board_no = #{boardNo}

UPDATE board.board
SET is_deleted = true
WHERE board_no = #{boardNo}

UPDATE board.board
SET board_count = board_count + 1
WHERE board_no = #{boardNo}

	    UPDATE board.board
    	SET board_like = board_like + 1
    	WHERE board_no = #{boardNo}
